 const c={STATUS:3,CS_OWNER:4,BRAND:5,APPOINTMENT_DATE:6,APPOINTMENT_TIME:7,CREATED_AT:2,PHONE:10,EMAIL:14,SOCIAL_USERNAME:22},names=['Alyssa Main','Alyssa Medical','Alyssa Aesthetics','GOS Beauty','Ineffable','Skin Light'];
 const values=Array(31).fill('');values[1]='2026-10-01';values[2]=r.status;values[3]='summer';values[4]=r.brand;values[5]=r.date;values[6]=r.time;values[9]=r.phone;values[25]=r.leadId;values[26]=r.appointmentId;
