// Native-like sheet for the actual scoped display and structural sorting code.
const arrivalHeaders=['品牌','電話','客人／預約','CS同事名','預約日期','時間','結果','到店日期','備註','檢查提示','Account','客人識別','電話末4','療程','分店','原預約日期（自動）','可追溯Book日期（自動）','Book日期來源（自動）','補充Book登記日期','穩定客戶識別（內部）','到店紀錄ID（內部）','客戶＋預約日期時間（內部）','Appointment ID','Schedule Revision','Queue State','Outcome Recorded At','Omni Lead ID','Booking Registered At','Record Origin','sortKey','來源','試做價','開單金額','總金額'];
function nativeSheet(headers,rows,headerRow=7){const state={headers:headers.slice(),rows:rows.map(r=>r.slice()),width:38,reads:0,dataReads:0,writes:[],insertions:0,deletions:0};const sh={state,getLastColumn:()=>state.headers.length,getMaxColumns:()=>state.width,getLastRow:()=>headerRow+state.rows.length,getMaxRows:()=>1000,insertRowsAfter(){},insertColumnAfter(c){state.insertions++;state.width++;state.rows.forEach(r=>r.splice(c,0,''));state.headers.splice(c,0,'');},deleteColumn(c){state.deletions++;state.width--;state.rows.forEach(r=>r.splice(c-1,1));state.headers.splice(c-1,1);while(state.headers.length&&!state.headers[state.headers.length-1])state.headers.pop();},getRange:(row,col,n,w)=>{const range={getValues:()=>{state.reads++;if(row>headerRow){state.dataReads++;if(state.beforeDataRead)state.beforeDataRead(state.dataReads);}return Array.from({length:n},(_,i)=>{const r=row+i===headerRow?state.headers:state.rows[row+i-headerRow-1]||[];return Array.from({length:w},(_,j)=>r[col-1+j]===undefined?'':r[col-1+j]);});},getDisplayValues:()=>range.getValues().map(r=>r.map(v=>String(v))),setValues:values=>{state.writes.push({row,col,n,w,values});values.forEach((vs,i)=>{const index=row+i-headerRow-1;while(state.rows.length<=index)state.rows.push([]);vs.forEach((v,j)=>state.rows[index][col-1+j]=v);});return range;},clearDataValidations:()=>range,setNumberFormat:()=>range,sort:({column})=>{const selected=state.rows.slice(row-headerRow-1,row-headerRow-1+n);selected.sort((a,b)=>String(a[column-1]).localeCompare(String(b[column-1])));state.rows.splice(row-headerRow-1,n,...selected);if(state.afterSort)state.afterSort();return range;}};return range;}};return sh;}
function nativeArrivalRow(a,cs='summer',trial=0,order=1280){const row=Array(38).fill('');const set=(h,v)=>row[arrivalHeaders.indexOf(h)]=v;Object.entries({'品牌':a.brand,'電話':a.phone,'客人／預約':'Synthetic label','CS同事名':cs,'預約日期':a.date,'時間':a.time,'結果':'待到店','到店日期':a.date,'備註':'Keep notes','Account':a.account,'穩定客戶識別（內部）':a.customerKey,'到店紀錄ID（內部）':a.queueId,'Appointment ID':a.id,'Omni Lead ID':a.leadId,'Record Origin':'managed','來源':'AD','試做價':trial,'開單金額':order,'總金額':'=SUM(AF8:AG8)'}).forEach(([h,v])=>set(h,v));return row;}
