test('actual native sorting preserves stable ownership CS/zero money/outcome/notes and becomes no-op',()=>{const box=load(),a=appointment(),b=appointment('b');a.date='2026-10-19';b.date='2026-10-18';const sh=nativeSheet(arrivalHeaders,[nativeArrivalRow(a,'sandy',0,1280),nativeArrivalRow(b,'summer',328,0)]),before=box.oa3RowSnapshot_(sh);assert.equal(box.oa3SortArrival_(sh).sorted,2);assert.equal(sh.state.rows[0][22],'b');assert.equal(sh.state.rows[1][22],'a');assert.deepEqual(clone(box.oa3RowSnapshot_(sh)),clone(before));assert.equal(sh.state.insertions,1);assert.equal(sh.state.deletions,1);sh.state.reads=sh.state.dataReads=0;assert.equal(box.oa3SortArrival_(sh).sorted,0);assert.equal(sh.state.dataReads,1);assert.equal(sh.state.reads,2);assert.equal(sh.state.insertions,1);});
