// Batch adapters must produce the original governed snapshot exactly while
// making a single provider matrix read. The original native values remain CAS.
function sourceNativeSheet(headers,rows,name='GOS Beauty'){const state={headers:headers.slice(),rows:rows.map(r=>r.slice()),rangeReads:0,dataRangeReads:0,displayRangeReads:0,names:0},matrix=()=>[state.headers.slice(),...state.rows.map(r=>r.slice())];const sh={state,getName:()=>{state.names++;return name;},getLastRow:()=>state.rows.length+1,getLastColumn:()=>state.headers.length,getMaxColumns:()=>Math.max(38,state.headers.length),getDataRange:()=>({getValues:()=>{state.dataRangeReads++;return matrix();},getDisplayValues:()=>{state.displayRangeReads++;return matrix().map(row=>row.map(v=>v instanceof Date?v.toISOString().slice(0,10):String(v)));}}),getRange:(r,c,n,w)=>({getValues:()=>{state.rangeReads++;return Array.from({length:n},(_,i)=>Array.from({length:w},(_,j)=>(matrix()[r+i-1]||[])[c+j-1]??''));},getDisplayValues:()=>{state.rangeReads++;return Array.from({length:n},(_,i)=>Array.from({length:w},(_,j)=>String((matrix()[r+i-1]||[])[c+j-1]??'')));}})};return sh;}
function sourceHeaders(box){return clone(vm.runInContext('OMNI_HEADERS.concat(OA2.ACCOUNT_HEADERS)',box));}
function sourceRow(headers,fields){const r=Array(headers.length).fill('');Object.entries(fields).forEach(([h,v])=>{const i=headers.indexOf(h);if(i>=0)r[i]=v;});return r;}
