test('manual source adapter caches repeated native timestamp formatting without changing current row tie-breaking',()=>{const box=load(),h=sourceHeaders(box),stamp=new Date('2026-10-18T16:00:00Z'),rows=Array.from({length:100},(_,i)=>sourceRow(h,{'最後更新日期':new Date(stamp),'電話':'10000001','Omni Lead ID':'synthetic_'+i}));let calls=0;const format=box.Utilities.formatDate;box.Utilities.formatDate=(...args)=>{calls++;return format(...args);};const actual=box.oa3ManualAccountSnapshot_(sourceNativeSheet(h,rows),'GOS Beauty',new Map());assert.equal(calls,1);assert.equal(actual.records.filter(r=>r.isCurrent).length,1);assert.equal(actual.records[99].isCurrent,true);assert.ok(actual.values.every(row=>row[0] instanceof Date));});
