for(const kind of ['base','cs','display','display_cs'])test('manual queue matrix adapter matches native governed parser: '+kind,()=>{const f=queueAdapterFixture(kind),expected=f.box.oa2ReadQueue_({getSheetByName:()=>f.sh},false);f.sh.state.reads=f.sh.state.dataReads=0;const actual=f.box.oa3ManualQueueSnapshot_(f.sh);assert.deepEqual(clone(actual),clone(expected));assert.equal(f.sh.state.dataRangeReads,1);assert.equal(f.sh.state.reads,0);assert.equal(actual[0].time,0);assert.ok(actual[0].date instanceof Date);assert.equal(actual[1].blank,true);assert.equal(actual[2].manualEntered,true);assert.equal(actual[2].blank,false);});
