function apiFixture(includeRegistry=false){const f=displayDiscoveryFixture();if(typeof f.box.oa3ManualBatchDisplayContext_!=='function')vm.runInContext(fs.readFileSync(root+'/fixtures/native-arrival/display-api-adapter.gs','utf8'),f.box);const sourceNames=f.names,allNames=['到店紀錄',...sourceNames,...(includeRegistry?['_appointment_registry']:[])],ledger=nativeSheet(['Appointment ID','Lead ID','Account','Customer Key','Phone Last8'],[['PRIVATE_APPOINTMENT','PRIVATE_LEAD','GOS Beauty','GOS Beauty|p:10000001','10000001']],1),realGet=f.ss.getSheetByName,counts={getId:0,sheetLookups:0,batch:0},calls=[],logs=[];f.ss.getId=()=>{counts.getId++;return'PRIVATE_SPREADSHEET_ID';};f.ss.getSheetByName=n=>{counts.sheetLookups++;return n==='_appointment_registry'?ledger:realGet(n);};const stringify=matrix=>matrix.map(row=>row.map(v=>v===undefined||v===null?'':v instanceof Date?v.toISOString().slice(0,10):String(v)));const matrices=allNames.map(n=>n==='到店紀錄'?[...Array.from({length:6},()=>Array(f.q.h.length).fill('')),f.q.sh.state.headers,...f.q.sh.state.rows]:n==='_appointment_registry'?[ledger.state.headers,...ledger.state.rows]:[f.sources[sourceNames.indexOf(n)].state.headers,...f.sources[sourceNames.indexOf(n)].state.rows]);const response={valueRanges:matrices.map(m=>({values:stringify(m).map(row=>{const copy=row.slice();while(copy.length&&copy[copy.length-1]==='')copy.pop();return copy;})}))};f.box.Sheets={Spreadsheets:{Values:{batchGet:(id,options)=>{counts.batch++;calls.push({id,options});if(options.valueRenderOption==='UNFORMATTED_VALUE')return{valueRanges:options.ranges.map(range=>{const match=/^'((?:[^']|'')+)'!A(\d+):[A-Z]+\d+$/.exec(range);assert.ok(match,range);const index=sourceNames.indexOf(match[1].replace(/''/g,"'")),row=Number(match[2]);assert.ok(index>=0);const values=f.sources[index].state.rows[row-2]||response.valueRanges[index+1].values[row-1];return values?{values:[values]}:{};})};return response;}}}};f.box.console.log=x=>logs.push(String(x));return{...f,ledger,counts,calls,logs,response,allNames};}
