test('API formatted display context produces same source/queue records and selection as native display',()=>{const f=apiFixture();delete f.box.Sheets;const expected=f.box.oa3MissingDisplayRead_(f.ss);const all=f.allNames,matrices=all.map(n=>n==='到店紀錄'?f.q.sh.getDataRange().getDisplayValues():f.sources[f.names.indexOf(n)].getDataRange().getDisplayValues());f.box.Sheets={Spreadsheets:{Values:{batchGet:()=>({valueRanges:matrices.map(values=>({values}))})}}};const o=f.box.oa3ManualBatchDisplayContext_(f.ss,{},'test',false);delete f.box.Sheets;const actual=f.box.oa3MissingDisplayRead_(o.spreadsheet);assert.deepEqual(clone(actual.queue),clone(expected.queue));for(let i=0;i<6;i++)for(const keyof of ['account','c','meta','width','values','records'])assert.deepEqual(clone(actual.snaps[i][keyof]),clone(expected.snaps[i][keyof]),keyof);assert.equal(actual.selection.items.length,expected.selection.items.length);assert.equal(actual.selection.skipped,expected.selection.skipped);});


test('merged display discovery calls exactly one API batch and touches no native provider matrix',()=>{const f=apiFixture(),o=f.box.oa3MissingDisplayRead_(f.ss,{},'integrated');assert.equal(o.readEngine,'sheets_api');assert.equal(f.counts.batch,1);assert.equal(f.counts.getId,1);assert.equal(f.counts.sheetLookups,0);assert.equal(f.q.sh.state.displayRangeReads,0);assert.equal(f.q.sh.state.dataRangeReads,0);assert.ok(f.sources.every(s=>s.state.displayRangeReads===0&&s.state.dataRangeReads===0));});
test('merged write discovery uses API index plus only targeted native queue/source CAS and retains real writable source sheet',()=>{const f=apiFixture(),row=sourceRow(f.h,{'跟進狀態':'已預約','電話':'10000001','Omni Lead ID':'lead_a','Appointment ID':'a','預約日期':new Date('2026-10-17T16:00:00Z'),'預約時間':0});f.sources[3].state.rows=[row];f.response.valueRanges[4].values=[f.h,row.map(v=>v instanceof Date?v.toISOString().slice(0,10):String(v))];f.q.sh.state.rows[0][4]='';f.response.valueRanges[0].values[7][4]='';const o=f.box.oa3MissingWriteRead_(f.ss,{});assert.equal(f.counts.batch,2);assert.equal(f.counts.sheetLookups,2);assert.equal(f.q.sh.state.dataRangeReads,0);assert.equal(f.q.sh.state.dataReads,1);assert.equal(f.sources[3].state.dataRangeReads,1);assert.ok(f.sources.every((s,i)=>i===3||s.state.dataRangeReads===0));assert.equal(o.snaps[0].sheet,f.sources[3]);assert.equal(o.selection.items.length,1);assert.equal(o.queue[0].time,0);assert.ok(o.snaps[0].values[0][5]instanceof Date);});
test('merged API ownership audit uses eighth matrix without native ledger lookup or customer data logging',()=>{const f=apiFixture(true),row=sourceRow(f.h,{'跟進狀態':'已預約','電話':'10000001','Omni Lead ID':'PRIVATE_LEAD','Appointment ID':'PRIVATE_APPOINTMENT','預約日期':'2026-10-18','預約時間':'15:00'});f.response.valueRanges[4].values=[f.h,row.map(String)];const q=f.response.valueRanges[0].values[7];q[4]=q[5]='';q[22]='PRIVATE_APPOINTMENT';q[26]='PRIVATE_LEAD';q[20]='PRIVATE_QUEUE';f.box.oa2Spreadsheet_=()=>f.ss;const o=f.box.auditManualScheduleGapsFast();assert.equal(o.readEngine,'sheets_api');assert.equal(o.scheduleGaps,1);assert.equal(o.ownershipMatches,1);assert.equal(f.counts.batch,2);assert.equal(f.calls[0].options.ranges.length,8);assert.equal(f.counts.sheetLookups,0);assert.equal(f.ledger.state.reads,0);const output=JSON.stringify(o)+f.logs.join('');for(const secret of ['PRIVATE_SPREADSHEET_ID','PRIVATE_APPOINTMENT','PRIVATE_LEAD','PRIVATE_QUEUE','10000001','GOS Beauty'])assert.equal(output.includes(secret),false,secret);});
test('merged API no-op endpoint returns read engine without registry context lock or native read',()=>{const f=apiFixture();f.box.oa2Spreadsheet_=()=>f.ss;f.box.PropertiesService={getDocumentProperties:()=>({getProperty:()=>null})};f.box.LockService={getDocumentLock:()=>{throw new Error('no-op must not lock');}};f.box.oa2Context_=()=>{throw new Error('no-op must not load context');};const o=f.box.syncMissingBookedArrivals();assert.equal(o.completed,true);assert.equal(o.noOp,true);assert.equal(o.readEngine,'sheets_api');assert.equal(f.counts.batch,1);assert.equal(f.counts.sheetLookups,0);assert.equal(f.q.sh.state.displayRangeReads,0);assert.equal(f.q.sh.state.dataRangeReads,0);});


test('onOpen exposes the manual sync menu without consulting current user owner email or properties',()=>{const b=load(),items=[];let title='',added=0;const menu={addItem:(label,handler)=>{items.push({label,handler});return menu;},addToUi:()=>{added++;return menu;}};b.Session=new Proxy({},{get(){throw new Error('menu must not inspect user identity');}});b.PropertiesService=new Proxy({},{get(){throw new Error('menu must not require user-specific properties');}});b.SpreadsheetApp={getUi:()=>({createMenu:name=>{title=name;return menu;}})};b.onOpen();assert.equal(title,'CS 工具');assert.equal(added,1);assert.ok(items.some(item=>item.label==='手動同步已預約'&&item.handler==='syncAllBookedArrivals'));assert.equal(typeof b.syncMissingBookedArrivals,'function');});
test('shared manual sidebar calls public RPC without an owner or email gate',()=>{const b=load();let shown;const ui={showSidebar:html=>shown=html};b.Session=new Proxy({},{get(){throw new Error('sidebar must not inspect user identity');}});b.SpreadsheetApp={getUi:()=>ui};b.HtmlService={createHtmlOutput:content=>{const html={content,setTitle:title=>{html.title=title;return html;}};return html;}};b.syncAllBookedArrivals();assert.equal(shown.title,'到店紀錄');assert.ok(shown.content.includes('.syncMissingBookedArrivals()'));assert.ok(shown.content.includes('withFailureHandler'));});
test('shared document finalization can be retried by another caller without UserProperties or identity lookup',()=>{const first=gapFixture();first.failCommit=true;assert.throws(()=>run(first),/commit failed/);assert.equal(first.props.ARRIVAL_MANUAL_MISSING_FINALIZE_PENDING,'1');const second=fixture();second.box.Session=new Proxy({},{get(){throw new Error('sync must not inspect caller identity');}});second.box.PropertiesService={getDocumentProperties:()=>({getProperty:k=>first.props[k]||null,setProperty:(k,v)=>first.props[k]=v,deleteProperty:k=>delete first.props[k]}),getUserProperties:()=>{throw new Error('shared sync must not use private user state');}};const receipt=run(second);assert.equal(receipt.completed,true);assert.equal(second.counts.context,0);assert.equal(second.counts.display,1);assert.equal(second.counts.sort,1);assert.equal(first.props.ARRIVAL_MANUAL_MISSING_FINALIZE_PENDING,undefined);});

console.log(JSON.stringify({passed:tests.length,failed:failures.length,tests,failures},null,2));if(failures.length)process.exitCode=1;
